CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_binding_health` AS
select `i`.`instance_id` AS `instance_id`,`i`.`iddev` AS `iddev`,`d`.`name` AS `dispositivo`,`i`.`subtype` AS `subtype`,`i`.`stable_key` AS `stable_key`,`i`.`instance_info_source` AS `instance_info_source`,`br`.`role_id` AS `role_id`,`br`.`relation_type` AS `relation_type`,`br`.`confidence` AS `confidence`,(case when isnull(`br`.`role_id`) then 'SIN_ROL' when (`br`.`confidence` = 'human_confirmed') then 'confirmado' when (`br`.`relation_type` = 'direct') then 'por_codigo' when (`br`.`relation_type` = 'derived') then 'heredado' else 'otro' end) AS `nivel_binding`,(case when exists(select 1 from (`sem_metric_binding` `b` join `metrics` `m` on((`m`.`id_metric` = `b`.`idmetric`))) where ((`b`.`instance_id` = `i`.`instance_id`) and (`b`.`status` = 'active') and (((`m`.`watch` is not null) and (`m`.`watch` <> '0') and (`m`.`watch` <> '')) or ((`m`.`subtype` collate utf8_spanish_ci) regexp '^(disp_icmp|mon_|w_mon_)') or ((coalesce(`m`.`c_label`,'') collate utf8_spanish_ci) regexp '[PWTIBD][0-9]+-SP[0-9]+-KPI[0-9]+') or ((coalesce(`m`.`label`,'') collate utf8_spanish_ci) regexp '[PWTIBD][0-9]+-SP[0-9]+-KPI[0-9]+')))) then 1 else 0 end) AS `importante`,(case when (`i`.`instance_info_source` = 'iid_weak') then 1 else 0 end) AS `identidad_debil`,(case when (`c`.`columna7` = 'unassigned') then 1 else 0 end) AS `col7_unassigned` from (((`sem_instance` `i` join `devices` `d` on((`d`.`id_dev` = `i`.`iddev`))) left join `devices_custom_data` `c` on((`c`.`id_dev` = `i`.`iddev`))) left join `sem_binding_role` `br` on((`br`.`instance_id` = `i`.`instance_id`))) where isnull(`i`.`valid_to`);
